import React, { useState } from 'react';
import { User,  Github, Globe, Save, FileText, Plus, Edit3 } from 'lucide-react';

const ProfilePage = () => {
  // 1. Dynamic State for Profile Data
  const [profileData, setProfileData] = useState({
    fullName: 'Ayoub',
    bio: 'L3 Information Technology Student | Full-stack Developer',
    email: 'ayoub@example.com',
    github: 'https://github.com/ayoub',
    portfolio: 'https://ayoub-dev.me',
    skills: ['React.js', 'Tailwind CSS', 'Node.js', 'Flutter']
  });

  // 2. Handle Input Changes
  const handleChange = (e) => {
    const { name, value } = e.target;
    setProfileData({
      ...profileData,
      [name]: value
    });
  };

  const handleSave = () => {
    console.log("Data saved to state:", profileData);
    alert("Profile updated successfully!");
  };

  const styles = {
    container: { backgroundColor: '#fdfbff', minHeight: '100vh', padding: '40px 20px', fontFamily: "'Segoe UI', sans-serif" },
    mainCard: { backgroundColor: 'white', maxWidth: '900px', margin: '0 auto', borderRadius: '20px', boxShadow: '0 10px 30px rgba(0,0,0,0.05)', overflow: 'hidden' },
    header: { backgroundColor: '#c5a3d1', height: '140px' },
    avatarSection: { marginTop: '-60px', padding: '0 40px', display: 'flex', alignItems: 'flex-end', gap: '20px' },
    avatar: { width: '120px', height: '120px', borderRadius: '50%', border: '5px solid white', backgroundColor: '#f3f4f6', display: 'flex', justifyContent: 'center', alignItems: 'center' },
    content: { padding: '30px 40px', display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '40px' },
    sectionTitle: { fontSize: '18px', fontWeight: 'bold', color: '#4a3f6b', marginBottom: '20px', display: 'flex', alignItems: 'center', gap: '10px', borderBottom: '2px solid #f3e8ff', paddingBottom: '10px' },
    inputGroup: { marginBottom: '20px' },
    label: { display: 'block', fontSize: '13px', fontWeight: '600', color: '#6b7280', marginBottom: '8px' },
    input: { width: '100%', padding: '12px', borderRadius: '10px', border: '1px solid #e5e7eb', backgroundColor: '#f9fafb', fontSize: '14px', outline: 'none', transition: 'border 0.2s' },
    skillTag: { backgroundColor: '#f3e8ff', color: '#7e22ce', padding: '6px 14px', borderRadius: '20px', fontSize: '12px', fontWeight: '600' },
    saveBtn: { backgroundColor: '#4a3f6b', color: 'white', padding: '12px 30px', borderRadius: '10px', border: 'none', fontWeight: 'bold', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '10px', margin: '0 40px 40px auto' }
  };

  return (
    <div style={styles.container}>
      <div style={styles.mainCard}>
        {/* Cover Header */}
        <div style={styles.header}></div>

        {/* Profile Identity */}
        <div style={styles.avatarSection}>
          <div style={styles.avatar}>
            <User size={60} color="#9ca3af" />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <h2 style={{ fontSize: '24px', fontWeight: 'bold', color: '#4a3f6b', margin: 0 }}>{profileData.fullName}</h2>
            <p style={{ color: '#6b7280', margin: 0 }}>IT Student - University Constantine 2</p>
          </div>
        </div>

        <div style={styles.content}>
          {/* Section 1: Personal Information */}
          <div>
            <h3 style={styles.sectionTitle}><Edit3 size={18} /> Personal Details</h3>
            <div style={styles.inputGroup}>
              <label style={styles.label}>Full Name</label>
              <input 
                style={styles.input} 
                name="fullName"
                value={profileData.fullName} 
                onChange={handleChange}
                placeholder="Enter your name"
              />
            </div>
            <div style={styles.inputGroup}>
              <label style={styles.label}>Bio / Professional Summary</label>
              <textarea 
                style={{ ...styles.input, height: '100px', resize: 'none' }} 
                name="bio"
                value={profileData.bio}
                onChange={handleChange}
                placeholder="Tell us about yourself..."
              />
            </div>
            <div style={styles.inputGroup}>
              <label style={styles.label}>Resume (CV)</label>
              <div style={{ ...styles.input, display: 'flex', justifyContent: 'space-between', alignItems: 'center', cursor: 'pointer' }}>
                <span style={{ color: '#9ca3af' }}>Upload New CV (PDF)</span>
                <FileText size={18} color="#7e22ce" />
              </div>
            </div>
          </div>

          {/* Section 2: Professional Links & Skills */}
          <div>
            <h3 style={styles.sectionTitle}><Github size={18} /> Online Presence</h3>
            <div style={styles.inputGroup}>
              <label style={styles.label}>GitHub Profile URL</label>
              <div style={{ position: 'relative' }}>
                <Github size={16} style={{ position: 'absolute', left: '12px', top: '14px', color: '#9ca3af' }} />
                <input 
                  style={{ ...styles.input, paddingLeft: '40px' }} 
                  name="github"
                  value={profileData.github}
                  onChange={handleChange}
                />
              </div>
            </div>
            <div style={styles.inputGroup}>
              <label style={styles.label}>Portfolio / Website</label>
              <div style={{ position: 'relative' }}>
                <Globe size={16} style={{ position: 'absolute', left: '12px', top: '14px', color: '#9ca3af' }} />
                <input 
                  style={{ ...styles.input, paddingLeft: '40px' }} 
                  name="portfolio"
                  value={profileData.portfolio}
                  onChange={handleChange}
                />
              </div>
            </div>

            <h3 style={{ ...styles.sectionTitle, marginTop: '20px' }}><Plus size={18} /> Technical Skills</h3>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
              {profileData.skills.map((skill, index) => (
                <span key={index} style={styles.skillTag}>{skill}</span>
              ))}
              <button style={{ ...styles.skillTag, backgroundColor: '#f3f4f6', color: '#4b5563', border: '1px dashed #d1d5db', cursor: 'pointer' }}>
                + Add Skill
              </button>
            </div>
          </div>
        </div>

        {/* Save Action */}
        <button style={styles.saveBtn} onClick={handleSave}>
          <Save size={18} /> Save Changes
        </button>
      </div>
    </div>
  );
};

export default ProfilePage;
